<script lang="ts">
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let kind=$state('provenance'),lot=$state(''),vineyard=$state(''),busy=$state(false),message=$state(''),links=$state<any>(null);
 async function create(){busy=true;try{const res=await fetch('/api/reports',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind,lot_id:lot||undefined,vineyard_id:vineyard||undefined})});const result=await res.json();if(res.ok)links=result;else message=t(result.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<section class="card"><h2>{t('versionedReports')}</h2><p class="muted">{t('reportNotOfficial')}</p><form onsubmit={(e)=>{e.preventDefault();create();}}><div class="grid"><label>{t('reportType')}<select bind:value={kind}>{#each ['provenance','field','costs','laboratory'] as k}<option value={k}>{t(k)}</option>{/each}</select></label><label>{t('lot_id')}<select bind:value={lot}><option value="">{t('all')}</option>{#each model.lots as l}<option value={l.id}>{l.code} · {l.name}</option>{/each}</select></label><label>{t('vineyard_id')}<select bind:value={vineyard}><option value="">{t('all')}</option>{#each model.vineyards as v}<option value={v.id}>{v.code} · {v.name}</option>{/each}</select></label></div><button disabled={busy}>{t('createReport')}</button></form>{#if links}<div class="actions"><a href={links.pdf}>PDF</a><a href={links.json}>JSON</a><span>{t('version')} 1 · {links.id}</span></div>{/if}<ul>{#each model.reports??[] as report}<li>{t(report.kind)} · {report.created_at} · <a href={'/api/reports?id='+report.id}>PDF</a> · <a href={'/api/reports?id='+report.id+'&format=csv'}>CSV</a></li>{/each}</ul><p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}.actions{display:flex;flex-wrap:wrap;gap:18px;margin-top:20px}</style>
